#include <iostream>

int* fabricar(int cantidad) {
    if (cantidad < 1 || cantidad > 4) {
        return nullptr;
    }
    int* base = new int[cantidad]{};
    for (int i = 0; i < cantidad; ++i) {
        base[i] = i + 2;
    }
    return base;
}

