#include <cstddef>
#include <iostream>
#include <span>

bool crear(int*& base, int& cantidad, int solicitados, int primero) {
    if (base != nullptr || cantidad != 0 || solicitados < 1 || solicitados > 4
        || primero < 0 || primero > 9) {
        return false;
    }
    if (solicitados - 1 > 9 - primero) {
        return false;
    }
    // Crea e inicializa el array y conserva su inicio y cantidad.
    return false;
}

bool retirar(int*& base, int& cantidad) {
    if (base == nullptr) {
        cantidad = 0;
        return false;
    }
    // Libera el array completo y deja su estado vacío.
    return false;
}

bool seleccionar(std::span<int> total, std::span<int>& vista, int inicio, int cantidad) {
    if (inicio < 0 || cantidad < 0) {
        return false;
    }
    const auto posicion = static_cast<std::size_t>(inicio);
    const auto longitud = static_cast<std::size_t>(cantidad);
    if (posicion > total.size() || longitud > total.size() - posicion) {
        return false;
    }
    vista = total.subspan(posicion, longitud);
    return true;
}

int main() {
    int ordenes = 0;
    if (!(std::cin >> ordenes) || ordenes < 1 || ordenes > 12) {
        return 1;
    }
    int* base = nullptr;
    int cantidad = 0;
    std::span<int> vista;
    for (int i = 0; i < ordenes; ++i) {
        int operacion = 0;
        int a = 0;
        int b = 0;
        if (!(std::cin >> operacion >> a >> b)) {
            vista = std::span<int>{};
            retirar(base, cantidad);
            return 1;
        }
        const char* estado = "Orden";
        if (operacion == 1) {
            if (crear(base, cantidad, a, b)) {
                vista = std::span<int>{base, static_cast<std::size_t>(cantidad)};
                estado = "Creado";
            } else {
                estado = "Rechazo";
            }
        } else if (operacion == 2) {
            std::span<int> total;
            if (base != nullptr) {
                total = std::span<int>{base, static_cast<std::size_t>(cantidad)};
            }
            estado = seleccionar(total, vista, a, b) ? "Seleccion" : "Rechazo";
        } else if (operacion == 3) {
            if (a < 0 || a > 9) {
                estado = "Rechazo";
            } else {
                for (int& dato : vista) {
                    dato = a;
                }
                estado = vista.empty() ? "Vacio" : "Cambio";
            }
        } else if (operacion == 4) {
            vista = std::span<int>{};
            estado = retirar(base, cantidad) ? "Liberado" : "Vacio";
        }
        std::cout << "Estado:" << estado << ";Cantidad:" << cantidad
                  << ";Vista:" << vista.size() << ";Datos:";
        if (base == nullptr) {
            std::cout << 'X';
        } else {
            for (int j = 0; j < cantidad; ++j) {
                if (j != 0) {
                    std::cout << ',';
                }
                std::cout << base[j];
            }
        }
        std::cout << '\n';
    }
    vista = std::span<int>{};
    const bool cierre = retirar(base, cantidad);
    std::cout << "Cierre:" << cierre << ";Cantidad:" << cantidad << ";Vista:" << vista.size() << '\n';
    return 0;
}

